mapper.select:
SELECT COUNT(1)
FROM base_class b
WHERE (
    b.one_class_no = #{classNo}
    OR b.two_class_no = #{classNo}
    OR b.three_class_no = #{classNo}
    OR b.four_class_no = #{classNo}
    OR b.five_class_no = #{classNo}
)

SELECT COUNT(1)
FROM base_department
WHERE store_no = #{storeNo}

SELECT TOP (#{param.limit}) store_no AS storeNo, MAX(store_name) AS storeName FROM base_department WHERE store_no IS NOT NULL AND LTRIM(RTRIM(store_no)) <> ''
AND store_format_no = #{param.retailTypeId}
AND business_circle_no = #{param.businessCircleId}
AND store_group_no = #{param.deptGroupId}
AND ( store_no LIKE CONCAT('%', #{param.keyword}, '%') OR store_name LIKE CONCAT('%', #{param.keyword}, '%') )
GROUP BY store_no ORDER BY store_no ASC
